#!/usr/bin/env bash
# shared/bin/scan_subsystem_joern.sh
#
# Runs Joern on an entire C source directory in a single session (one CPG build)
# with SCS006 and/or SCS007 detection queries.  Produces a summary comparable
# to the one generated by scan_subsystem.sh so the two tools can be contrasted.
#
# Usage:
#   bash scan_subsystem_joern.sh \
#       --target  /path/to/linux/net \
#       --detectors SCS006,SCS007 \
#       --out  /path/to/results/net_scan_joern
#
# Output files:
#   <out>/findings_all.json   — one JSON object per line (same schema as SmellDetect)
#   <out>/summary.txt         — human-readable summary (mirrors SmellDetect format)
#   <out>/joern_raw.txt       — raw stdout from Joern (for debugging)
#   <out>/joern_timing.raw    — /usr/bin/time output
#
# Requires: joern + c2cpg.sh (on PATH / /opt/joern/joern-cli/), python3, /usr/bin/time
#
# Two-step approach to avoid OOM on large corpora:
#   Step 1: c2cpg.sh builds the structural CPG (no dataflow overlay) with more heap
#   Step 2: joern --script loads the CPG with importCpg() and runs structural queries
#
# The --heap option controls JVM heap for both steps (default: 6g).
set -euo pipefail

# ── defaults ────────────────────────────────────────────────────────────────
TARGET_DIR=""
DETECTORS="SCS006,SCS007"
OUT_DIR=""
HEAP="6g"
C2CPG="${C2CPG:-/opt/joern/joern-cli/c2cpg.sh}"

# ── argument parsing ─────────────────────────────────────────────────────────
while [ $# -gt 0 ]; do
    case "$1" in
        --target)     TARGET_DIR="$2"; shift 2 ;;
        --detectors)  DETECTORS="$2";  shift 2 ;;
        --out)        OUT_DIR="$2";    shift 2 ;;
        --heap)       HEAP="$2";       shift 2 ;;
        *) echo "Unknown option: $1"; exit 1 ;;
    esac
done

if [ -z "$TARGET_DIR" ] || [ -z "$OUT_DIR" ]; then
    echo "Usage: $0 --target DIR --detectors SCS006[,SCS007] --out OUTDIR"
    exit 1
fi

TARGET_DIR="$(cd "$TARGET_DIR" && pwd)"
mkdir -p "$OUT_DIR"

# validate c2cpg
if [ ! -x "$C2CPG" ]; then
    echo "ERROR: c2cpg.sh not found at $C2CPG"
    echo "       Set C2CPG=/path/to/c2cpg.sh or install Joern to /opt/joern"
    exit 1
fi

# ── detector flags ───────────────────────────────────────────────────────────
RUN_SCS006=false
RUN_SCS007=false
IFS=',' read -r -a DET_ARRAY <<< "$DETECTORS"
for d in "${DET_ARRAY[@]}"; do
    case "$d" in
        SCS006) RUN_SCS006=true ;;
        SCS007) RUN_SCS007=true ;;
        *) echo "Unknown detector: $d (supported: SCS006, SCS007)"; exit 1 ;;
    esac
done

FINDINGS_JSON="$OUT_DIR/findings_all.json"
SUMMARY_TXT="$OUT_DIR/summary.txt"
JOERN_RAW="$OUT_DIR/joern_raw.txt"
JOERN_TIME="$OUT_DIR/joern_timing.raw"
CPG_TIME="$OUT_DIR/cpg_build_timing.raw"
CPG_BIN="$OUT_DIR/cpg.bin"
SCALA_SCRIPT=$(mktemp /tmp/joern_net_scan_XXXXXX.sc)

echo "════════════════════════════════════════════════════════════"
echo " Joern Subsystem Scan"
echo " Target    : $TARGET_DIR"
echo " Detectors : $DETECTORS"
echo " Heap      : $HEAP"
echo " Output    : $OUT_DIR"
echo " Date      : $(date)"
echo "════════════════════════════════════════════════════════════"
echo ""

# ── Step 1: build structural CPG with c2cpg.sh ───────────────────────────────
# c2cpg produces only the base CPG (no dataflow overlay) — much lower memory.
echo "Step 1: Building CPG with c2cpg.sh -J-Xmx${HEAP} …"
if [ "$(uname)" = "Darwin" ]; then
    TIME_CMD_CPG="/usr/bin/time -l"
else
    TIME_CMD_CPG="/usr/bin/time -v"
fi

# shellcheck disable=SC2086
$TIME_CMD_CPG "$C2CPG" \
    "-J-Xmx${HEAP}" \
    "$TARGET_DIR" \
    --output "$CPG_BIN" \
    > "$OUT_DIR/cpg_build.log" 2>"$CPG_TIME" || {
    echo "ERROR: c2cpg.sh failed. See $OUT_DIR/cpg_build.log"
    rm -f "$SCALA_SCRIPT"
    exit 1
}
echo "CPG built → $CPG_BIN"
echo ""

echo "Step 2: Running Joern queries against CPG …"
echo "Building Scala query script …"

# ── build Scala script ────────────────────────────────────────────────────────
{
cat << 'SCALA_HEADER'
// Joern batch scan — SCS006 (Integer Overflow) and/or SCS007 (Signed/Unsigned)
// Generated by scan_subsystem_joern.sh
// Uses Cpg.withStorage (direct CPG open) — skips dataflow overlay entirely.
// This avoids OOM on large corpora while still giving full access to structural
// CPG nodes (calls, arguments, identifiers, methods, files, line numbers).

import io.shiftleft.codepropertygraph.Cpg
import io.shiftleft.semanticcpg.language._

val cpg = Cpg.withStorage("CPG_BIN_PLACEHOLDER")

SCALA_HEADER

if [ "$RUN_SCS006" = "true" ]; then
cat << 'SCS006_BLOCK'
// ── SCS006: Unguarded arithmetic (integer overflow risk) ─────────────────────
// Traverse method→call (not call→method) to avoid missing containsIn edges
// on operator nodes that have no enclosing method context in the CPG.
{
  val maxConstants = Set(
    "INT_MAX","CHAR_MAX","SHRT_MAX","SHORT_MAX","UINT_MAX",
    "INT64_MAX","LLONG_MAX","ULONG_MAX","SIZE_MAX"
  )

  // Guard names (comparison operators)
  val guardOpNames = Set(
    "<operator>.lessThan", "<operator>.lessEqualsThan",
    "<operator>.greaterThan", "<operator>.greaterEqualsThan"
  )

  // Arithmetic operator names
  val arithOpNames = Set(
    "<operator>.multiplication", "<operator>.addition",
    "<operator>.preIncrement",   "<operator>.postIncrement"
  )

  val findings006 = cpg.method
    .filter(_.name != "<global>")
    .flatMap { m =>
      // Is this method guarded? (has a comparison against a max constant)
      // Use .ast.isCall / .ast.isIdentifier — works on base CPG without overlays
      val hasGuard = m.ast.isCall
        .filter(c => guardOpNames.contains(c.name))
        .ast.isIdentifier
        .exists(i => maxConstants.contains(i.name))

      if (hasGuard) Iterator.empty
      else {
        val fname = m.filename
        val mname = m.name
        m.ast.isCall
          .filter(c => arithOpNames.contains(c.name))
          .map { c =>
            val line = c.lineNumber.getOrElse(-1)
            s"SCS006_FINDING:$fname:$line:${c.name}:$mname"
          }
      }
    }
    .distinct.l

  findings006.foreach(println)
  println(s"SCS006_COUNT:${findings006.size}")
}
SCS006_BLOCK
fi

if [ "$RUN_SCS007" = "true" ]; then
cat << 'SCS007_BLOCK'
// ── SCS007: Signed-to-unsigned conversion at size sinks ──────────────────────
// Traverse method→call (not call→method) for the same reason as SCS006.
{
  val sinkNames = Set("malloc", "memcpy", "memmove", "strncpy")

  val findings007 = cpg.method
    .filter(_.name != "<global>")
    .flatMap { m =>
      // Has positivity guard: (> 0) or (>= 1) anywhere in method
      val hasGuard = m.ast.isCall
        .filter(c => c.name == "<operator>.greaterThan" || c.name == "<operator>.greaterEqualsThan")
        .ast.isLiteral
        .exists(l => l.code == "0" || l.code == "1")

      if (hasGuard) Iterator.empty
      else {
        val fname = m.filename
        val mname = m.name
        m.ast.isCall
          .filter(c => sinkNames.contains(c.name))
          .map { c =>
            val line = c.lineNumber.getOrElse(-1)
            s"SCS007_FINDING:$fname:$line:${c.name}:$mname"
          }
      }
    }
    .distinct.l

  findings007.foreach(println)
  println(s"SCS007_COUNT:${findings007.size}")
}
SCS007_BLOCK
fi

echo 'cpg.close()'
echo 'println("JOERN_SCAN_COMPLETE")'

} > "$SCALA_SCRIPT"

# substitute the CPG path in the Scala script (escape slashes for sed)
ESCAPED_CPG=$(printf '%s\n' "$CPG_BIN" | sed 's/[\/&]/\\&/g')
sed -i '' "s|CPG_BIN_PLACEHOLDER|${ESCAPED_CPG}|g" "$SCALA_SCRIPT"

# ── run Joern with timing ────────────────────────────────────────────────────
if [ "$(uname)" = "Darwin" ]; then
    TIME_CMD="/usr/bin/time -l"
else
    TIME_CMD="/usr/bin/time -v"
fi

# shellcheck disable=SC2086
JAVA_TOOL_OPTIONS="-Xmx${HEAP}" \
$TIME_CMD joern --script "$SCALA_SCRIPT" \
    > "$JOERN_RAW" 2>"$JOERN_TIME" || {
    echo "ERROR: Joern exited with non-zero status."
    echo "       Check $JOERN_RAW and $JOERN_TIME for details."
    rm -f "$SCALA_SCRIPT"
    exit 1
}

rm -f "$SCALA_SCRIPT"

# ── check completion ─────────────────────────────────────────────────────────
if ! grep -q "JOERN_SCAN_COMPLETE" "$JOERN_RAW"; then
    echo "WARNING: JOERN_SCAN_COMPLETE marker not found — scan may be incomplete."
fi

echo "Joern finished. Parsing results …"

# ── parse results into JSON + summary via Python3 ────────────────────────────
python3 - "$JOERN_RAW" "$JOERN_TIME" "$CPG_TIME" "$OUT_DIR" "$TARGET_DIR" "$DETECTORS" << 'PYEOF'
import sys, re, json, os
from datetime import datetime

raw_file, time_file, cpg_time_file, out_dir, target_dir, detectors_str = sys.argv[1:]
findings_path = os.path.join(out_dir, "findings_all.json")
summary_path  = os.path.join(out_dir, "summary.txt")

# ── parse findings ─────────────────────────────────────────────────────────
findings = []
scs006_count = 0
scs007_count = 0

rule_map = {
    "<operator>.multiplication": "unchecked_multiply",
    "<operator>.addition":       "unchecked_add",
    "<operator>.preIncrement":   "unchecked_increment",
    "<operator>.postIncrement":  "unchecked_increment",
    "malloc":   "signedUnsignedConversion",
    "memcpy":   "signedUnsignedConversion",
    "memmove":  "signedUnsignedConversion",
    "strncpy":  "signedUnsignedConversion",
}

detector_map = {
    "SCS006": "joern_scs006",
    "SCS007": "joern_scs007",
}

rule_counts   = {}
detect_counts = {}
file_counts   = {}

with open(raw_file, "r", errors="replace") as fh:
    for line in fh:
        line = line.rstrip()

        m6 = re.match(r'^SCS006_FINDING:(.+):(-?\d+):(.+):(.+)$', line)
        m7 = re.match(r'^SCS007_FINDING:(.+):(-?\d+):(.+):(.+)$', line)
        m6c = re.match(r'^SCS006_COUNT:(\d+)$', line)
        m7c = re.match(r'^SCS007_COUNT:(\d+)$', line)

        if m6c:
            scs006_count = int(m6c.group(1))
            continue
        if m7c:
            scs007_count = int(m7c.group(1))
            continue

        prefix = scs_id = op = meth = fpath = lineno = None
        if m6:
            scs_id, fpath, lineno, op, meth = "SCS006", m6.group(1), int(m6.group(2)), m6.group(3), m6.group(4)
        elif m7:
            scs_id, fpath, lineno, op, meth = "SCS007", m7.group(1), int(m7.group(2)), m7.group(3), m7.group(4)
        else:
            continue

        # make path relative to target_dir
        rel = fpath
        if fpath.startswith(target_dir):
            rel = fpath[len(target_dir):].lstrip("/")

        rule  = rule_map.get(op, op)
        det   = detector_map[scs_id]

        finding = {
            "scs": scs_id,
            "rule": rule,
            "detector": det,
            "file": rel,
            "line": lineno,
            "function": meth,
            "severity": "warning",
            "classification": "smell",
            "message": f"Joern: {op} in {meth}",
            "tool": "joern"
        }
        findings.append(finding)
        rule_counts[rule]  = rule_counts.get(rule, 0) + 1
        detect_counts[det] = detect_counts.get(det, 0) + 1
        file_counts[rel]   = file_counts.get(rel, 0) + 1

# write findings JSON
with open(findings_path, "w") as fh:
    for f in findings:
        fh.write(json.dumps(f) + "\n")

def parse_time_raw(path):
    """Return (wall_s, rss_mb) from a /usr/bin/time output file."""
    wall_s = 0.0
    rss_mb = 0.0
    try:
        with open(path, "r", errors="replace") as fh:
            tdata = fh.read()
        wm = re.search(r'([\d.]+)\s+real', tdata)
        if wm:
            wall_s = float(wm.group(1))
        rm = re.search(r'(\d+)\s+maximum resident set size', tdata)
        if rm:
            rss_mb = int(rm.group(1)) / 1024 / 1024
        if not wm:
            wm2 = re.search(r'Elapsed.*?(\d+):(\d+\.\d+)', tdata)
            if wm2:
                wall_s = int(wm2.group(1)) * 60 + float(wm2.group(2))
        if not rm:
            rm2 = re.search(r'Maximum resident set size.*?:\s*(\d+)', tdata)
            if rm2:
                rss_mb = int(rm2.group(1)) / 1024
    except Exception as e:
        print(f"WARNING: could not parse {path}: {e}", file=sys.stderr)
    return wall_s, rss_mb

# ── parse timing ──────────────────────────────────────────────────────────
cpg_wall_s, cpg_rss_mb   = parse_time_raw(cpg_time_file)
query_wall_s, query_rss_mb = parse_time_raw(time_file)
total_wall_s = cpg_wall_s + query_wall_s
peak_rss_mb  = max(cpg_rss_mb, query_rss_mb)

# ── write summary ─────────────────────────────────────────────────────────
n_findings = len(findings)
n_files_with = len(file_counts)

# estimate files scanned (all .c files in target)
n_files_scanned = 0
for root, dirs, files in os.walk(target_dir):
    for fname in files:
        if fname.endswith(".c"):
            n_files_scanned += 1

n_files_clean = max(0, n_files_scanned - n_files_with)
pct_with  = round(100 * n_files_with  / n_files_scanned) if n_files_scanned else 0
pct_clean = round(100 * n_files_clean / n_files_scanned) if n_files_scanned else 0

# top 20 files
top20 = sorted(file_counts.items(), key=lambda x: -x[1])[:20]

lines = []
SEP = "═" * 60
lines.append(SEP)
lines.append(" Joern Scan Summary")
lines.append(f" Target       : {target_dir}")
lines.append(f" SCS detectors: {detectors_str}")
lines.append(f" Date         : {datetime.now().strftime('%Y-%m-%d %H:%M')}")
lines.append(SEP)
lines.append("")
lines.append(f" Files scanned       : {n_files_scanned}")
lines.append(f" Files with findings : {n_files_with}  ({pct_with}%)")
lines.append(f" Files clean         : {n_files_clean}  ({pct_clean}%)")
lines.append("")
lines.append(f" Total findings      : {n_findings}")
lines.append(f"   warning/smell      : {n_findings}  (100%)")
lines.append("")
lines.append("── By rule " + "─" * 49)
for rule, cnt in sorted(rule_counts.items(), key=lambda x: -x[1]):
    lines.append(f"  {rule:<36} {cnt:>5}")
lines.append("")
lines.append("── By detector " + "─" * 45)
for det, cnt in sorted(detect_counts.items(), key=lambda x: -x[1]):
    lines.append(f"  {det:<36} {cnt:>5}")
lines.append("")
lines.append("── Top 20 files by finding count " + "─" * 26)
for rel, cnt in top20:
    lines.append(f"  {cnt:>4}  {rel}")
lines.append("")
lines.append("── Timing & Memory " + "─" * 41)
lines.append(f"  CPG build  (c2cpg.sh)            : {cpg_wall_s:.3f}s   peak {cpg_rss_mb:.1f} MB")
lines.append(f"  Query      (joern --script)      : {query_wall_s:.3f}s   peak {query_rss_mb:.1f} MB")
lines.append(f"  Total wall time                  : {total_wall_s:.3f}s")
lines.append(f"  Peak RSS   (max of both phases)  : {peak_rss_mb:.1f} MB")
lines.append("")
lines.append(f" Findings JSON : {findings_path}")
lines.append(SEP)
lines.append("")

with open(summary_path, "w") as fh:
    fh.write("\n".join(lines))

print("\n".join(lines))
print(f"\nFindings JSON : {findings_path}")
PYEOF
